using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> typedInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person>: Type={typedInfo.Type.Name}, Kind={typedInfo.Kind}");

// 2) Probe without throwing — TryGetTypeInfo returns false instead of an exception
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, kind={probed?.Kind}");

// Probe for a type whose metadata might NOT be available (e.g. with a restricted resolver)
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (info) => {
            if (info.Type == typeof(Order))
                throw new NotSupportedException("Order not supported");
        }}
    }
};

bool foundOrder = restrictedOptions.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderInfo);
Console.WriteLine($"TryGetTypeInfo(Order) on restricted resolver: found={foundOrder}, info={orderInfo?.Type.Name ?? "null"}");

public record Person(string Name, int Age);
public record Order(int Id, decimal Total);
EOF
