using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata — cast to JsonTypeInfo<T>
JsonTypeInfo<Person> typedInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person>: Type={typedInfo.Type.Name}, Kind={typedInfo.Kind}");

// 2) Probe without throwing — TryGetTypeInfo returns false if resolver can't provide it
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, kind={probed?.Kind}");

// Use a resolver that only knows about Person — Order is unknown
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new PersonOnlyResolver()
    )
};

bool foundPerson = restrictedOptions.TryGetTypeInfo(typeof(Person), out _);
bool foundOrder  = restrictedOptions.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderInfo);
Console.WriteLine($"Restricted resolver — Person available: {foundPerson}");
Console.WriteLine($"Restricted resolver — Order available: {foundOrder}, info is null: {orderInfo is null}");

public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

/// A resolver that only provides metadata for Person.
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}
EOF
